async fn reopen(path: &Path) -> WabiDbEngine {
    let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(5);
    loop {
        match WabiDbEngine::open(config(path)).await {
            Ok(engine) => return engine,
            Err(crate::error::WabiError::AlreadyRunning)
                if tokio::time::Instant::now() < deadline =>
            {
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
            }
            Err(error) => panic!("pre-versioning fixture did not open: {error}"),
        }
    }
}

fn copy_dir(from: &Path, to: &Path) {
    std::fs::create_dir_all(to).unwrap();
    for entry in std::fs::read_dir(from).unwrap() {
        let entry = entry.unwrap();
        let target = to.join(entry.file_name());
        if entry.file_type().unwrap().is_dir() {
            copy_dir(&entry.path(), &target);
        } else {
            std::fs::copy(entry.path(), &target).unwrap();
        }
    }
}

/// Copy the committed data directory (without `expected.txt`) to a scratch
/// directory the engine may write to.
fn scratch_copy() -> tempfile::TempDir {
    let scratch = tempfile::tempdir().unwrap();
    copy_dir(&fixture_dir().join(ENGINE_DIR), &scratch.path().join("data"));
    scratch
}

fn expected() -> String {
    std::fs::read_to_string(fixture_dir().join("expected.txt")).unwrap()
}

/// Generates the fixture. Run once, before any record encoder changed:
/// `WABIDB_WRITE_PRE_VERSIONING_FIXTURE=1 cargo test -p wabidb --lib -- --ignored write_pre_versioning_fixture`
#[tokio::test]
#[ignore = "writes tests/fixtures; see the module docs before running"]
async fn write_pre_versioning_fixture() {
    if std::env::var_os("WABIDB_WRITE_PRE_VERSIONING_FIXTURE").is_none() {
        return;
    }
    let root = fixture_dir();
    let data = root.join(ENGINE_DIR);
    assert!(!data.exists(), "refusing to overwrite {}", data.display());
    std::fs::create_dir_all(&data).unwrap();
    let engine = WabiDbEngine::open(config(&data)).await.unwrap();
    for event in fixture_events() {
        engine.get_or_create_stream_key(&event.stream_id).await.unwrap();
        let event_type = event.event_type.clone();
        let (response_tx, _response_rx) = tokio::sync::oneshot::channel();
        engine
            .run_command(CommandCommit {
                room_owner_precondition: None,
                caller_user_id: 7,
                caller_device_id: "fixture".into(),
                command_name: format!("fixture_{event_type}"),
                idempotency_key: None,
                events: vec![event],
                essential: true,
                response_tx,
            })
            .await
            .unwrap_or_else(|e| panic!("{event_type} rejected: {e}"));
    }
    let described = describe_state(&engine.projection_state());
    assert!(!described.contains("DECODE ERROR"), "{described}");
    drop(engine);
    drop(super::wait_for_stopped_engine(&data).await);
    std::fs::write(root.join("expected.txt"), described).unwrap();
}

/// Snapshot present: the projection rows on disk are the old raw postcard
/// bytes, and every one must still decode to what it decoded to before.
#[tokio::test]
async fn pre_versioning_snapshot_still_decodes() {
    let scratch = scratch_copy();
    let data = scratch.path().join("data");
    assert!(ProjectionState::snapshot_path(&data).exists());
    let engine = reopen(&data).await;
    assert_eq!(describe_state(&engine.projection_state()), expected());
}

/// Snapshot removed: the engine replays every old durable event from the log
/// through today's decoders and must rebuild the same projection state.
#[tokio::test]
async fn pre_versioning_log_replays_to_the_same_state() {
    let scratch = scratch_copy();
    let data = scratch.path().join("data");
    std::fs::remove_file(ProjectionState::snapshot_path(&data)).unwrap();
    let engine = reopen(&data).await;
    let state = engine.projection_state();
    assert_eq!(state.applied_commit_seq(), fixture_events().len() as u64);
    assert_eq!(describe_state(&state), expected());
}

/// An upgraded server: old events, then new versioned ones in the same log.
/// A full replay must read both, and the old entries must be unchanged.
#[tokio::test]
async fn pre_versioning_log_with_new_writes_replays() {
    let scratch = scratch_copy();
    let data = scratch.path().join("data");
    let engine = reopen(&data).await;
    let mut member = sample::channel_member();
    member.user_id = 4_200_000_002;
    member.nick = None;
    let new_event = event(
        "channel_members:ch_general",
        1,
        "channel_member_added",
        channel_members::encode_record(&member),
    );
    assert!(crate::format::versioned::is_versioned(&new_event.plaintext));
    engine.get_or_create_stream_key(&new_event.stream_id).await.unwrap();
    let (response_tx, _response_rx) = tokio::sync::oneshot::channel();
    engine
        .run_command(CommandCommit {
            room_owner_precondition: None,
            caller_user_id: 7,
            caller_device_id: "fixture".into(),
            command_name: "fixture_new_member".into(),
            idempotency_key: None,
            events: vec![new_event],
            essential: true,
            response_tx,
        })
        .await
        .unwrap();
    drop(engine);
    drop(super::wait_for_stopped_engine(&data).await);
    std::fs::remove_file(ProjectionState::snapshot_path(&data)).unwrap();

    let engine = reopen(&data).await;
    let state = engine.projection_state();
    assert_eq!(state.applied_commit_seq(), fixture_events().len() as u64 + 1);
    let mut members = channel_members::ChannelMembersProjection::list_members(&state, "ch_general")
        .unwrap();
    members.sort_by_key(|m| m.user_id);
    assert_eq!(members, vec![sample::channel_member(), member]);
    let described = describe_state(&state);
    let lines: Vec<&str> = described.lines().collect();
    for old in expected().lines().filter(|line| !line.starts_with("channel_membership_versions ")) {
        assert!(lines.contains(&old), "old entry changed or missing: {old}");
    }
    assert!(!described.contains("DECODE ERROR"), "{described}");
}

/// Offline inspection replays the whole log and compares the result with the
/// saved projection. Replay re-encodes some rows, so a row the old build saved
/// as raw postcard comes out of this build's replay with a version-1 header.
/// That is the same content, and inspection must say the two match.
async fn inspect(data: &Path) -> crate::error::Result<bool> {
    inspect_receipt(data).await.map(|receipt| receipt.persisted_projection_matches)
}

async fn inspect_receipt(
    data: &Path,
) -> crate::error::Result<crate::engine::offline_inspect::InspectionReceipt> {
    use crate::engine::offline_inspect::{inspect_frozen, InspectionLimits};
    let indexed =
        crate::commit_index::batcher::read_all_entries(&data.join("global/commit-index")).unwrap();
    let seq = indexed.iter().map(|entry| entry.commit_seq).max().unwrap();
    let prefix = crate::replication::commit_prefix_fingerprint(&indexed, seq);
    inspect_frozen(data, &BOOTSTRAP, seq, &prefix, InspectionLimits::default())
        .await
        .map(|inspected| inspected.receipt)
}

#[tokio::test]
async fn pre_versioning_directory_passes_offline_inspection() {
    let scratch = scratch_copy();
    let matches = inspect(&scratch.path().join("data")).await;
    assert!(matches!(matches, Ok(true)), "{:?}", matches.map_err(|e| e.to_string()));
    // The fixture has no read model, so its messages have no saved state to
    // compare: the snapshot's message indexes are not what the engine loads.
    let receipt = inspect_receipt(&scratch.path().join("data")).await.unwrap();
    assert!(!receipt.read_model_compared);
}

/// The fixture's snapshot was saved by a build that kept messages in it, with
/// a created message's channel and author entries keyed by
/// `msg_{commit_seq:x}` (Task 3.4), and the fixture has no read model. Opening
/// it does not repair or load those entries: messages are rebuilt from the log
/// into the read model, and the snapshot file is left alone until the engine
/// next saves one, which then holds no message index.
#[tokio::test]
async fn opening_rebuilds_messages_from_the_log_not_the_snapshot() {
    let scratch = scratch_copy();
    let data = scratch.path().join("data");
    let snapshot = ProjectionState::snapshot_path(&data);
    let before = std::fs::read(&snapshot).unwrap();
    let index_names = |bytes: &[u8]| -> Vec<String> {
        let json: serde_json::Value = serde_json::from_slice(bytes).unwrap();
        json["indexes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|index| index[0].as_str().unwrap().to_owned())
            .collect()
    };
    assert!(
        index_names(&before).iter().any(|name| name == "messages_by_channel"),
        "the fixture must still hold the old message indexes, or this test proves nothing"
    );
    assert!(!ProjectionState::read_model_path(&data).exists());
    let (saved, _) = ProjectionState::load_snapshot(&data).unwrap().unwrap();
    assert!(describe_messages(&saved).is_empty());

    let engine = reopen(&data).await;
    assert!(ProjectionState::read_model_path(&data).is_file());
    assert_eq!(std::fs::read(&snapshot).unwrap(), before, "open rewrote the snapshot");
    assert_eq!(describe_messages(&engine.projection_state()).len(), 5);
    assert_eq!(describe_state(&engine.projection_state()), expected());
    drop(engine);
    drop(super::wait_for_stopped_engine(&data).await);

    let after = index_names(&std::fs::read(&snapshot).unwrap());
    for legacy in crate::engine::locks::LEGACY_MESSAGE_INDEXES {
        assert!(!after.iter().any(|name| name == legacy), "{legacy} saved again");
    }
    // The next open uses the read model as it is and reads the same.
    let engine = reopen(&data).await;
    assert_eq!(describe_state(&engine.projection_state()), expected());
}

/// The same after an upgrade: this build opened the old directory, wrote a
/// versioned record, and saved a snapshot that mixes old and new rows.
#[tokio::test]
async fn upgraded_directory_passes_offline_inspection() {
    let scratch = scratch_copy();
    let data = scratch.path().join("data");
    let engine = reopen(&data).await;
    let mut member = sample::channel_member();
    member.user_id = 4_200_000_002;
    let new_event = event(
        "channel_members:ch_general",
        1,
        "channel_member_added",
        channel_members::encode_record(&member),
    );
    engine.get_or_create_stream_key(&new_event.stream_id).await.unwrap();
    let (response_tx, _response_rx) = tokio::sync::oneshot::channel();
    engine
        .run_command(CommandCommit {
            room_owner_precondition: None,
            caller_user_id: 7,
            caller_device_id: "fixture".into(),
            command_name: "fixture_new_member".into(),
            idempotency_key: None,
            events: vec![new_event],
            essential: true,
            response_tx,
        })
        .await
        .unwrap();
    drop(engine);
    drop(super::wait_for_stopped_engine(&data).await);
    assert!(ProjectionState::snapshot_path(&data).exists());

    let matches = inspect(&data).await;
    assert!(matches!(matches, Ok(true)), "{:?}", matches.map_err(|e| e.to_string()));
    // This build wrote a read model on the way; its rows were compared too.
    assert!(inspect_receipt(&data).await.unwrap().read_model_compared);
}

// ---------------------------------------------------------------------------
// Task 3.1b: event payloads that stayed raw postcard after Task 3.1.
//
// The fixture has none of these events and must not be regenerated, so the
// old-format events are built here from the golden bytes (exactly what an
// older build wrote), each followed by the same event from today's encoder.
// ---------------------------------------------------------------------------

/// Old and new `forum_post_voted`, `forum_post_solution_set`, `user_deleted`
/// and `dm_onetime_prekey_consumed` events against the fixture's records.
fn raw_payload_events() -> Vec<EventToWrite> {
    use crate::domain::UserDeleted;
    use crate::projections::user_deletion;
    use sample::{
        bytes, DM_PREKEY_CONSUMED_LEGACY, FORUM_SOLUTION_LEGACY, FORUM_VOTE_LEGACY,
        USER_DELETED_LEGACY,
    };
    let down_vote = forum::VotePayload { direction: "down".into(), ..sample::forum_vote() };
    let second_prekey = dm_identities::ConsumedPayload {
        prekey_public: "otk2".into(),
        ..sample::dm_prekey_consumed()
    };
    vec![
        // The fixture's thread got a post id from its commit seq, so put the
        // sample post the golden payloads name in place first (an edit is an
        // upsert that keeps the ids it is given).
        event(
            "ch_forum",
            6,
            "forum_post_edited",
            forum::encode_record(&sample::forum_post()),
        ),
        // Up-votes post_1 (legacy), then down-votes it (versioned).
        event("ch_forum", 6, "forum_post_voted", bytes(FORUM_VOTE_LEGACY)),
        event("ch_forum", 6, "forum_post_voted", forum::encode_vote(&down_vote)),
        // Marks post_1 the solution, once in each format.
        event("ch_forum", 6, "forum_post_solution_set", bytes(FORUM_SOLUTION_LEGACY)),
        event(
            "ch_forum",
            6,
            "forum_post_solution_set",
            forum::encode_solution(&sample::forum_solution()),
        ),
        // Deletes the channel member's user (legacy), then user 7 (versioned).
        event("users", 6, "user_deleted", bytes(USER_DELETED_LEGACY)),
        event(
            "users",
            6,
            "user_deleted",
            user_deletion::encode_payload(&UserDeleted { user_id: 7 }),
        ),
        // Consumes both of user 9's one-time prekeys, one in each format.
        event("dm_identities:9", 6, "dm_onetime_prekey_consumed", bytes(DM_PREKEY_CONSUMED_LEGACY)),
        event(
            "dm_identities:9",
            6,
            "dm_onetime_prekey_consumed",
            dm_identities::encode_consumed(&second_prekey),
        ),
    ]
}

/// Open the fixture copy at `data`, commit [`raw_payload_events`] one command
/// each, and stop the engine (which saves a snapshot).
async fn write_raw_payload_events(data: &Path) {
    let engine = reopen(data).await;
    for event in raw_payload_events() {
        engine.get_or_create_stream_key(&event.stream_id).await.unwrap();
        let event_type = event.event_type.clone();
        let (response_tx, _response_rx) = tokio::sync::oneshot::channel();
        engine
            .run_command(CommandCommit {
                room_owner_precondition: None,
                caller_user_id: 7,
                caller_device_id: "fixture".into(),
                command_name: format!("fixture_{event_type}"),
                idempotency_key: None,
                events: vec![event],
                essential: true,
                response_tx,
            })
            .await
            .unwrap_or_else(|e| panic!("{event_type} rejected: {e}"));
    }
    drop(engine);
    drop(super::wait_for_stopped_engine(data).await);
}

/// What [`raw_payload_events`] must have done to the fixture's state.
fn assert_raw_payload_events_applied(state: &ProjectionState) {
    let post = forum::ForumProjection::get_post(state, "ch_forum", "thr_1", "post_1")
        .unwrap()
        .unwrap();
    let before = sample::forum_post();
    assert_eq!((post.votes_up, post.votes_down), (before.votes_up + 1, before.votes_down + 1));
    assert!(post.is_solution);
    assert!(!crate::projections::user_deletion::user_exists(state, 7));
    assert!(channel_members::ChannelMembersProjection::list_members(state, "ch_general")
        .unwrap()
        .is_empty());
    let identity = dm_identities::DmIdentitiesProjection::get_identity(state, 9, "dev-phone")
        .unwrap()
        .unwrap();
    assert!(identity.one_time_prekeys.is_empty(), "{:?}", identity.one_time_prekeys);
}

/// Old-format and new-format payload events in one log both replay, with the
/// snapshot removed so every event goes through today's decoders.
#[tokio::test]
async fn raw_event_payloads_replay_in_both_formats() {
    let scratch = scratch_copy();
    let data = scratch.path().join("data");
    write_raw_payload_events(&data).await;
    std::fs::remove_file(ProjectionState::snapshot_path(&data)).unwrap();

    let engine = reopen(&data).await;
    let state = engine.projection_state();
    assert_eq!(
        state.applied_commit_seq(),
        (fixture_events().len() + raw_payload_events().len()) as u64
    );
    assert_raw_payload_events_applied(&state);
    assert!(!describe_state(&state).contains("DECODE ERROR"));
}

/// Offline inspection replays the same mixed log and must match the snapshot
/// this build saved. None of these handlers stores its payload bytes (votes and
/// solutions re-encode the forum post, `user_deleted` only removes rows, the
/// prekey event re-encodes the identity), so they cannot cause a legacy-versus-
/// version-1 fingerprint difference; what this checks is that inspection's
/// replay decodes both formats of every one.
#[tokio::test]
async fn raw_event_payloads_pass_offline_inspection() {
    let scratch = scratch_copy();
    let data = scratch.path().join("data");
    write_raw_payload_events(&data).await;
    assert!(ProjectionState::snapshot_path(&data).exists());

    let matches = inspect(&data).await;
    assert!(matches!(matches, Ok(true)), "{:?}", matches.map_err(|e| e.to_string()));
    // This build wrote a read model on the way; its rows were compared too.
    assert!(inspect_receipt(&data).await.unwrap().read_model_compared);
}
